<script setup lang="ts">
import {onMounted,onUnmounted,ref,watch} from 'vue';
import type {Resolution} from './sync-resolution';
const props=defineProps<{decision:Resolution;check:{id:string;decision_id:string;status:string;snapshot?:unknown};disabled:boolean;syncActive?:boolean}>(),emit=defineEmits<{authenticationRequired:[]}>();
type Run={id:string;config_id:string;status:string;started_at_utc:string;finished_at_utc:string|null;step_count:number;confirmed:number;error:string};
const labels:Record<string,string>={running:'执行中',verification_pending:'已执行，等待完整同步复核',complete:'完整同步复核完成',conflict:'执行前或复核发现变化',failed:'执行未完成',unknown:'结果未知，保持隔离',interrupted:'进程中断，先核对原批次'};
const ack=ref(false),busy=ref(false),consumed=ref(false),record=ref<Run|null>(null),error=ref(''),received=ref('');
const verification=ref<Run|null>(null),verifyUncertain=ref(false),verificationReceived=ref('');
let active=true,generation=0,controller:AbortController|undefined,timer:ReturnType<typeof setTimeout>|undefined;
const current=(n:number)=>active&&n===generation;
const id=(x:unknown)=>typeof x==='string'&&/^[a-f0-9]{32}$/.test(x);
const utc=(x:unknown)=>typeof x==='string'&&x.endsWith('Z')&&Number.isFinite(Date.parse(x))&&!x.startsWith('0001-');
function parse(x:any):Run{if(!x||!id(x.id)||x.config_id!==props.decision.source_config.id||!Object.hasOwn(labels,x.status)||!utc(x.started_at_utc)||x.finished_at_utc!==null&&!utc(x.finished_at_utc)||x.status!=='running'&&!utc(x.finished_at_utc)||x.step_count!==(props.decision.subtree_review?Number(props.decision.subtree_review.plan_step_count):props.decision.effects.length)||!Number.isSafeInteger(x.step_count)||!Number.isSafeInteger(x.confirmed)||x.confirmed<0||x.confirmed>x.step_count||typeof x.error!=='string'||record.value&&x.id!==record.value.id)throw Error('执行批次身份或状态证据无效');return x}
function parseVerification(x:any):Run{if(!x||!id(x.id)||x.config_id!==props.decision.source_config.id||!['running','complete','conflict','failed','unknown','interrupted'].includes(x.status)||!utc(x.started_at_utc)||x.finished_at_utc!==null&&!utc(x.finished_at_utc)||x.status!=='running'&&!utc(x.finished_at_utc)||x.step_count!==0||x.confirmed!==0||typeof x.error!=='string'||record.value&&x.id===record.value.id)throw Error('完整复核范围或状态证据无效');return x}
async function verify(post=false){
 if(!active||busy.value||props.disabled)return;
 if(post&&(verifyUncertain.value||props.syncActive||record.value?.status!=='verification_pending'||record.value.confirmed!==record.value.step_count||verification.value?.status==='complete'||verification.value?.status==='running'))return;
 const n=++generation;clearTimeout(timer);controller?.abort();controller=new AbortController();busy.value=true;if(post)verifyUncertain.value=true;
 try{const response=await fetch('/api/sync/resolutions/'+props.decision.id+'/verification',{method:post?'POST':'GET',credentials:'same-origin',signal:controller.signal,headers:post?{'Content-Type':'application/json'}:{},body:post?'{}':undefined});if(!current(n))return;if(response.status===401){stop();emit('authenticationRequired');return}if(!post&&response.status===404){error.value='尚未读到完整复核记录，不会自动启动复核。';verifyUncertain.value=false;return}if(!response.ok)throw Error((await response.text()).slice(0,1000)||'完整复核记录暂不可读');const value=await response.json();if(!current(n))return;verification.value=parseVerification(value);verificationReceived.value=new Date().toISOString();verifyUncertain.value=false;error.value='';if(verification.value.status==='running')timer=setTimeout(()=>{void verify()},2000)}catch(e){if(current(n))error.value=(e instanceof Error?e.message:String(e))+'；请只读查询完整复核记录，不会自动重发。'}finally{if(current(n))busy.value=false}
}
async function request(post=false){if(!active||busy.value||props.disabled)return;if(post&&(!ack.value||consumed.value||props.syncActive||props.check.status!=='verified'||!props.check.snapshot||props.check.decision_id!==props.decision.id))return;
 const n=++generation;clearTimeout(timer);controller?.abort();controller=new AbortController();busy.value=true;if(post){consumed.value=true;ack.value=false}
 try{const response=await fetch('/api/sync/resolutions/'+props.decision.id+'/execution',{method:post?'POST':'GET',credentials:'same-origin',signal:controller.signal,headers:post?{'Content-Type':'application/json'}:{},body:post?JSON.stringify({check_id:props.check.id,confirm:true}):undefined});if(!current(n))return;if(response.status===401){stop();emit('authenticationRequired');return}if(!post&&response.status===404){error.value='尚未读到本决策的执行准入记录；不会自动发送。';return}if(!response.ok)throw Error((await response.text()).slice(0,1000)||'执行记录暂不可读');const value=await response.json();if(!current(n))return;record.value=parse(value);received.value=new Date().toISOString();error.value='';if(record.value.status==='running')timer=setTimeout(()=>{void request()},2000)}catch(e){if(current(n))error.value=(e instanceof Error?e.message:String(e))+(post?'；执行准入结果待查，请只读查询原批次，不会自动重发。':'；保留上次读取结果。')}finally{if(current(n))busy.value=false}
}
function reset(){generation++;clearTimeout(timer);controller?.abort();busy.value=false;ack.value=false;consumed.value=false;record.value=null;error.value='';received.value='';verification.value=null;verifyUncertain.value=false;verificationReceived.value=''}
function stop(){active=false;generation++;clearTimeout(timer);controller?.abort();busy.value=false;ack.value=false}
function restore(){active=true;ack.value=false;if(verification.value||verifyUncertain.value)void verify();else if(record.value||consumed.value)void request()}
watch(()=>[props.decision.id,props.check.id],reset);watch(()=>props.disabled,v=>{if(v)stop();else active=true});
onMounted(()=>{window.addEventListener('pagehide',stop);window.addEventListener('pageshow',restore)});onUnmounted(()=>{stop();window.removeEventListener('pagehide',stop);window.removeEventListener('pageshow',restore)});
</script>
<template><section class="resolution-execution"><h4>执行本项固定决策</h4><p class="muted">将按上方固定路径与步骤执行，并在服务端再次核对两端。每个决策只准入一个执行批次，重复请求不会重放；完成步骤后仍需完整同步复核。</p><label class="execution-ack"><input v-model="ack" type="checkbox" data-testid="sync-resolution-execution-ack" :disabled="busy||disabled||syncActive||consumed||check.status!=='verified'||!check.snapshot"/>我已核对保留版本、固定路径和备份要求，确认执行本项。</label><div class="execution-actions"><button class="button primary" data-testid="sync-conflict-execute" :disabled="busy||disabled||syncActive||consumed||!ack||check.status!=='verified'||!check.snapshot" @click="request(true)">确认执行固定决策</button><button class="button secondary compact" data-testid="sync-resolution-execution-read" :disabled="busy||disabled" @click="request()">读取原执行批次</button></div><p v-if="busy" role="status">正在提交或读取；离开页面不会自动重发执行。</p><p v-if="error" role="alert" class="notice danger">{{error}}</p><section v-if="record" data-testid="sync-resolution-execution-result" class="execution-observation"><strong>{{verification?.status==='complete'?'本项已关联完整同步复核':labels[record.status]}}</strong><p>执行批次 {{record.id}}<br>步骤确认 {{record.confirmed}} / {{record.step_count}}<br>开始 UTC {{record.started_at_utc}}<br>结束 UTC {{record.finished_at_utc||'尚无结束记录'}}<br>本页读取 UTC {{received}}</p><p v-if="record.error">{{record.error}}</p><a class="button secondary compact" :href="'/api/sync/runs/'+record.id+'?export=1'">导出完整步骤与回执</a><p v-if="record.status==='verification_pending'&&verification?.status!=='complete'" class="muted">所选内容已执行并核对；原冲突和共同基线仍保留，尚未标为全部解决。</p><section class="full-verification"><h4>完整同步复核与基线</h4><p class="muted">重新遍历整个同步关系；仅当所选输出仍匹配、范围内没有剩余变化，才提交共同基线并建立完成关联。原执行回执保留，不改写旧冲突。</p><div class="execution-actions"><button class="button primary" data-testid="sync-resolution-verify" :disabled="busy||disabled||syncActive||verifyUncertain||record.status!=='verification_pending'||record.confirmed!==record.step_count||verification?.status==='complete'||verification?.status==='running'" @click="verify(true)">完整复核并建立基线</button><button class="button secondary compact" data-testid="sync-resolution-verification-read" :disabled="busy||disabled" @click="verify()">读取完整复核 / 完成关联</button></div><section v-if="verification" data-testid="sync-resolution-verification-result" class="execution-observation"><strong>{{verification.status==='complete'?'完整复核通过，已建立共同基线':labels[verification.status]}}</strong><p>复核批次 {{verification.id}}<br>开始 UTC {{verification.started_at_utc}}<br>结束 UTC {{verification.finished_at_utc||'尚无结束记录'}}<br>本页读取 UTC {{verificationReceived}}</p><p v-if="verification.error">{{verification.error}}</p><p v-if="verification.status==='complete'" class="muted">完成关联是该批次时点的历史证据；以后仍按新变化进行同步检查。</p><a class="button secondary compact" :href="'/api/sync/runs/'+verification.id+'?export=1'">导出完整复核与基线证据</a></section></section><p v-if="['unknown','interrupted'].includes(record.status)" class="notice">不要重发此决策；先查看原批次证据核对实际结果。</p></section></section></template>
<style scoped>.resolution-execution{margin-top:14px;border-top:1px solid #dbe4ef;padding-top:12px}.full-verification{margin-top:16px;border-top:1px solid #dce5ef;padding-top:10px}.execution-ack{display:flex;gap:8px;align-items:flex-start;margin:12px 0;font-size:13px}.execution-ack input{margin-top:3px}.execution-actions{display:flex;gap:10px;flex-wrap:wrap}.execution-observation{background:#f5f8fc;border:1px solid #dce5ef;border-radius:8px;padding:12px 14px;margin-top:12px;overflow-wrap:anywhere}</style>
